WITH "g1" AS (SELECT "t1"."region" AS "region", "t1"."branch_id" AS "branch_id", MAX("t1"."branch_name") AS "branch_id_label", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN "t0"."net_amount" END) AS "net_revenue" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t1"."region", "t1"."branch_id"), "ranked" AS (SELECT "g1"."region" AS "region", "g1"."branch_id" AS "branch_id", "g1"."branch_id_label" AS "branch_id_label", "g1"."net_revenue" AS "net_revenue", RANK() OVER (PARTITION BY "g1"."region" ORDER BY "g1"."net_revenue" DESC) AS "rnk" FROM "g1") SELECT "region", "branch_id", "branch_id_label", "net_revenue" FROM "ranked" WHERE "rnk" <= 2 ORDER BY "region", "net_revenue" DESC
